cat > /tmp/spec/probe.sh <<'SH'
#!/bin/bash
B=${BATBIN:-/workspace/executable}
run() {
  echo "########## CMD: $*"
  out=$("$B" "$@" 2>/tmp/.err </dev/null); rc=$?
  echo "--exit=$rc"
  if [ -n "$out" ]; then echo "--stdout:"; printf '%s\n' "$out" | sed 's/^/  |/'; else echo "--stdout: (empty)"; fi
  if [ -s /tmp/.err ]; then echo "--stderr:"; sed 's/^/  |/' /tmp/.err; else echo "--stderr: (empty)"; fi
}
SH
